func main() {
    colors := []string{"red", "green", "blue"}
    for _, color := range colors {
        fmt.Println(color)
    }
}

exercises.starter_code:
package main

import "fmt"

func main() {
    score := 85
    // Use if-else if-else chain
}

exercises.solution:
package main

import "fmt"


func main() {
    score := 85
    if score >= 90 {
        fmt.Println("A")
    } else if score >= 80 {
        fmt.Println("B")
    } else if score >= 70 {
        fmt.Println("C")
    } else if score >= 60 {
        fmt.Println("D")
    } else {
        fmt.Println("F")
    }
}

exercises.starter_code:
package main

import "fmt"

func main() {
    // Infinite for loop with break at 5
}

exercises.solution:
package main

import "fmt"

func main() {
    i := 1
    for {
        if i >= 5 {
            break
        }
        fmt.Println(i)
        i++
    }
}

